import{sameOriginUrl}from"../same-origin-url";beforeEach((()=>{window.location="https://shop.test/buy"})),describe("sameOriginUrl",(()=>{it.each([["https://shop.test/thanks?sc=1#x","https://shop.test/thanks?sc=1#x"],["/thanks","/thanks"],["thanks","thanks"],["https:evil.example","https:evil.example"]])("keeps a same-origin url %p",((e,t)=>{expect(sameOriginUrl(e)).toBe(t)})),it.each([["https://evil.example/phish"],["//evil.example/phish"],["https://shop.test.evil.example/"],["https://shop.test:8443/thanks"],["http://shop.test/thanks"],["http:evil.example"],["javascript:alert(1)"],["data:text/html,hi"]])("refuses %p",(e=>{expect(sameOriginUrl(e)).toBeNull()})),it("is null for an empty value",(()=>{expect(sameOriginUrl("")).toBeNull(),expect(sameOriginUrl(null)).toBeNull(),expect(sameOriginUrl(void 0)).toBeNull()}))}));